__global__ void mse_forward_kernel(const half* predictions, const half* targets, half* output, int64_t total_elements) {
    extern __shared__ half shared_mem[];

    int tid = threadIdx.x;
    int bid = blockIdx.x;
    int block_size = blockDim.x;

    // Initialize shared memory
    half sum = __float2half(0.0f);

    // Each thread processes multiple elements if needed
    for (int i = bid * block_size + tid; i < total_elements; i += gridDim.x * block_size) {
        half diff = predictions[i] - targets[i];
        half squared = diff * diff;
        sum = __hadd(sum, squared);
    }

    shared_mem[tid] = sum;
    __syncthreads();

    // Reduction within block
    for (int s = block_size / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_mem[tid] = __hadd(shared_mem[tid], shared_mem[tid + s]);
        }
        __syncthreads();
    }

    // Write block result to global memory
    if (tid == 0) {
        atomicAdd(output, shared_mem[0]);
    }
}

__global__ void mse_backward_kernel(const half* predictions, const half* targets, half* grad_predictions, half* grad_targets, int64_t total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        half diff = predictions[idx] - targets[idx];
        half grad_val = __hmul(__float2half(2.0f), diff);
        grad_predictions[idx] = grad_val;
        grad_targets[idx] = __hneg(grad_val);
    }
}

