extern "C" void mse_forward(const half* predictions, const half* targets, half* output, int64_t total_elements) {
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;
    const int max_blocks = 65535;

    // Limit number of blocks to avoid exceeding hardware limits
    int actual_blocks = min(num_blocks, max_blocks);

    // Initialize output to zero
    cudaMemset(output, 0, sizeof(half));

    // Launch kernel with shared memory
    size_t shared_mem_size = block_size * sizeof(half);
    mse_forward_kernel<<<actual_blocks, block_size, shared_mem_size>>>(
        predictions, targets, output, total_elements);

    // Wait for completion
    cudaDeviceSynchronize();
}

